bbox_to_cds_area <- function(bbox_path, buffer_degrees=0.25) { if(!requireNamespace("sf",quietly=TRUE)) stop("Package 'sf' is required"); b <- sf::st_read(bbox_path, quiet=TRUE); if(is.na(sf::st_crs(b))) stop("Bounding box has no CRS"); b <- sf::st_transform(sf::st_make_valid(b),4326); e <- sf::st_bbox(sf::st_union(b)); west <- max(-180,unname(e[["xmin"]])-buffer_degrees); east <- min(180,unname(e[["xmax"]])+buffer_degrees); south <- max(-90,unname(e[["ymin"]])-buffer_degrees); north <- min(90,unname(e[["ymax"]])+buffer_degrees); if(north<=south || east<=west) stop("Invalid CDS area"); c(north=north,west=west,south=south,east=east) }
diagnose_spatial_domain <- function(template_path,bbox_path) { if(!requireNamespace("terra",quietly=TRUE)||!requireNamespace("sf",quietly=TRUE)) stop("terra and sf are required"); r <- terra::rast(template_path); b <- sf::st_make_valid(sf::st_read(bbox_path,quiet=TRUE)); if(is.na(sf::st_crs(b))) stop("Bounding box has no CRS"); b4326 <- sf::st_transform(b,4326); area <- bbox_to_cds_area(bbox_path); has_crs <- nzchar(terra::crs(r)); tb <- sf::st_as_sfc(sf::st_bbox(r)); list(template_crs=if(has_crs) terra::crs(r,proj=FALSE) else NA_character_, template_crs_wkt=if(has_crs) terra::crs(r) else NA_character_, template_crs_missing=!has_crs, template_is_geographic=if(has_crs) terra::is.lonlat(r) else NA, extent=as.vector(terra::ext(r)), resolution=terra::res(r), dimensions=c(nrow=terra::nrow(r),ncol=terra::ncol(r)), origin=terra::origin(r), ncell=terra::ncell(r), non_na_count=as.numeric(terra::global(!is.na(r),"sum",na.rm=FALSE)[1,1]), bbox_crs=sf::st_crs(b)$wkt, bbox_valid=all(sf::st_is_valid(b)), bbox_extent_native=as.vector(sf::st_bbox(b)), bbox_extent_4326=as.vector(sf::st_bbox(b4326)), boundary_overlaps_template=if(has_crs) any(sf::st_intersects(b4326,sf::st_transform(tb,4326),sparse=FALSE)) else NA, template_intersects_boundary=if(has_crs) any(sf::st_intersects(tb,sf::st_transform(b,terra::crs(r)),sparse=FALSE)) else NA, cds_area=area) }
